mapper.select:
SELECT ( SELECT COUNT(*) FROM tbl_router_info R_CNT WHERE 1=1
AND R_CNT.company_id = #{companyId}
) AS manageDeviceCnt, COUNT(*) AS totalDeviceCnt, SUM(CASE WHEN UPPER(TRIM(A.CurrentRadioType)) = 'LTE-R' THEN 1 ELSE 0 END) AS lteCnt, SUM(CASE WHEN UPPER(TRIM(A.CurrentRadioType)) = 'VHF' THEN 1 ELSE 0 END) AS vhfCnt, SUM(CASE WHEN TRIM(A.AutoSwitchingRadio) = '1' THEN 1 ELSE 0 END) AS autoSwitchCnt, ROUND(AVG(CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRP), 'DBM', ''), 'DB', '')), '') AS SIGNED)), 1) AS avgRsrp, ROUND(AVG(CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRQ), 'DBM', ''), 'DB', '')), '') AS SIGNED)), 1) AS avgRsrq, SUM(CASE WHEN CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRP), 'DBM', ''), 'DB', '')), '') AS SIGNED) < -90 OR CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRQ), 'DBM', ''), 'DB', '')), '') AS SIGNED) < -10 THEN 1 ELSE 0 END) AS cautionDeviceCnt, DATE_FORMAT(MAX(A.RCV_DT), '%Y-%m-%d %H:%i:%s') AS lastRcvDt FROM tbl_last_data A INNER JOIN tbl_router_info R ON A.VoLTE_NUM = R.volte_num WHERE 1=1
AND R.company_id = #{companyId}

SELECT DATE_FORMAT(A.RCV_DT, '%H:%i') AS label, COUNT(*) AS totalCnt, SUM(CASE WHEN UPPER(TRIM(A.CurrentRadioType)) = 'LTE-R' THEN 1 ELSE 0 END) AS lteCnt, SUM(CASE WHEN UPPER(TRIM(A.CurrentRadioType)) = 'VHF' THEN 1 ELSE 0 END) AS vhfCnt FROM tbl_receive_data A INNER JOIN tbl_router_info R ON A.VoLTE_NUM = R.volte_num WHERE A.RCV_DT >= DATE_SUB(NOW(), INTERVAL 12 MINUTE)
AND R.company_id = #{companyId}
GROUP BY DATE_FORMAT(A.RCV_DT, '%Y-%m-%d %H:%i'), DATE_FORMAT(A.RCV_DT, '%H:%i') ORDER BY DATE_FORMAT(A.RCV_DT, '%Y-%m-%d %H:%i') ASC

SELECT T.radioType, T.cnt, ROUND(T.cnt * 100 / NULLIF(T.totalCnt, 0), 0) AS ratio FROM ( SELECT CASE WHEN UPPER(TRIM(A.CurrentRadioType)) = 'LTE-R' THEN 'LTE-R' WHEN UPPER(TRIM(A.CurrentRadioType)) = 'VHF' THEN 'VHF' ELSE '기타' END AS radioType, COUNT(*) AS cnt, SUM(COUNT(*)) OVER() AS totalCnt FROM tbl_last_data A INNER JOIN tbl_router_info R ON A.VoLTE_NUM = R.volte_num WHERE 1=1
AND R.company_id = #{companyId}
GROUP BY CASE WHEN UPPER(TRIM(A.CurrentRadioType)) = 'LTE-R' THEN 'LTE-R' WHEN UPPER(TRIM(A.CurrentRadioType)) = 'VHF' THEN 'VHF' ELSE '기타' END ) T ORDER BY CASE T.radioType WHEN 'LTE-R' THEN 1 WHEN 'VHF' THEN 2 ELSE 3 END

SELECT S.sortOrder AS sortOrder, S.status AS status, S.statusClass AS statusClass, S.rangeText AS rangeText, COALESCE(T.cnt, 0) AS cnt FROM ( SELECT 1 AS sortOrder, '정상' AS status, 'normal' AS statusClass, 'RSRP >= -90 dBm' AS rangeText UNION ALL SELECT 2, '주의', 'caution', '-100 <= RSRP < -90 dBm' UNION ALL SELECT 3, '경고', 'warning', '-110 <= RSRP < -100 dBm' UNION ALL SELECT 4, '심각', 'critical', 'RSRP < -110 dBm' ) S LEFT JOIN ( SELECT CASE WHEN CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRP), 'DBM', ''), 'DB', '')), '') AS SIGNED) < -110 THEN 4 WHEN CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRP), 'DBM', ''), 'DB', '')), '') AS SIGNED) < -100 THEN 3 WHEN CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRP), 'DBM', ''), 'DB', '')), '') AS SIGNED) < -90 THEN 2 ELSE 1 END AS sortOrder, COUNT(*) AS cnt FROM tbl_last_data A INNER JOIN tbl_router_info R ON A.VoLTE_NUM = R.volte_num WHERE 1=1
AND R.company_id = #{companyId}
GROUP BY CASE WHEN CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRP), 'DBM', ''), 'DB', '')), '') AS SIGNED) < -110 THEN 4 WHEN CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRP), 'DBM', ''), 'DB', '')), '') AS SIGNED) < -100 THEN 3 WHEN CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRP), 'DBM', ''), 'DB', '')), '') AS SIGNED) < -90 THEN 2 ELSE 1 END ) T ON S.sortOrder = T.sortOrder ORDER BY S.sortOrder ASC

SELECT S.sortOrder AS sortOrder, S.status AS status, S.statusClass AS statusClass, S.rangeText AS rangeText, COALESCE(T.cnt, 0) AS cnt FROM ( SELECT 1 AS sortOrder, '정상' AS status, 'normal' AS statusClass, 'RSRQ >= -10 dB' AS rangeText UNION ALL SELECT 2, '주의', 'caution', '-15 <= RSRQ < -10 dB' UNION ALL SELECT 3, '경고', 'warning', '-18 <= RSRQ < -15 dB' UNION ALL SELECT 4, '심각', 'critical', 'RSRQ < -18 dB' ) S LEFT JOIN ( SELECT CASE WHEN CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRQ), 'DBM', ''), 'DB', '')), '') AS SIGNED) < -18 THEN 4 WHEN CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRQ), 'DBM', ''), 'DB', '')), '') AS SIGNED) < -15 THEN 3 WHEN CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRQ), 'DBM', ''), 'DB', '')), '') AS SIGNED) < -10 THEN 2 ELSE 1 END AS sortOrder, COUNT(*) AS cnt FROM tbl_last_data A INNER JOIN tbl_router_info R ON A.VoLTE_NUM = R.volte_num WHERE 1=1
AND R.company_id = #{companyId}
GROUP BY CASE WHEN CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRQ), 'DBM', ''), 'DB', '')), '') AS SIGNED) < -18 THEN 4 WHEN CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRQ), 'DBM', ''), 'DB', '')), '') AS SIGNED) < -15 THEN 3 WHEN CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRQ), 'DBM', ''), 'DB', '')), '') AS SIGNED) < -10 THEN 2 ELSE 1 END ) T ON S.sortOrder = T.sortOrder ORDER BY S.sortOrder ASC

SELECT T.VoLTE_NUM AS volteNum, T.CAR_NUM AS carNum, T.CurrentRadioType AS currentRadioType, T.RSRP AS rsrp, T.rsrpNum AS rsrpNum, CASE WHEN T.rsrpNum < -110 THEN '심각' WHEN T.rsrpNum < -100 THEN '경고' WHEN T.rsrpNum < -90 THEN '주의' ELSE '정상' END AS rsrpStatus, CASE WHEN T.rsrpNum < -110 THEN 'critical' WHEN T.rsrpNum < -100 THEN 'warning' WHEN T.rsrpNum < -90 THEN 'caution' ELSE 'normal' END AS rsrpStatusClass, T.RSRQ AS rsrq, T.rsrqNum AS rsrqNum, CASE WHEN T.rsrqNum < -18 THEN '심각' WHEN T.rsrqNum < -15 THEN '경고' WHEN T.rsrqNum < -10 THEN '주의' ELSE '정상' END AS rsrqStatus, CASE WHEN T.rsrqNum < -18 THEN 'critical' WHEN T.rsrqNum < -15 THEN 'warning' WHEN T.rsrqNum < -10 THEN 'caution' ELSE 'normal' END AS rsrqStatusClass, DATE_FORMAT(T.RCV_DT, '%H:%i:%s') AS rcvTime, DATE_FORMAT(T.RCV_DT, '%Y-%m-%d %H:%i:%s') AS rcvDtSort FROM ( SELECT A.VoLTE_NUM, A.CAR_NUM, A.CurrentRadioType, A.RSRP, A.RSRQ, A.RCV_DT, CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRP), 'DBM', ''), 'DB', '')), '') AS SIGNED) AS rsrpNum, CAST(NULLIF(TRIM(REPLACE(REPLACE(UPPER(A.RSRQ), 'DBM', ''), 'DB', '')), '') AS SIGNED) AS rsrqNum FROM tbl_last_data A INNER JOIN tbl_router_info R ON A.VoLTE_NUM = R.volte_num WHERE 1=1
AND R.company_id = #{companyId}
) T ORDER BY CASE WHEN T.rsrqNum IS NULL THEN 1 ELSE 0 END ASC, T.rsrqNum ASC, CASE WHEN T.rsrpNum IS NULL THEN 1 ELSE 0 END ASC, T.rsrpNum ASC, T.RCV_DT DESC
LIMIT 7
